import log from 'loglevel';
import { hostedLogValues } from './hostedLogPrivacy';

export const enableHostedLogPrivacy = (): void => {
  const methodFactory = log.methodFactory;
  log.methodFactory = (method, level, name) => {
    const write = methodFactory(method, level, name);
    return (message: unknown, ...values: unknown[]) =>
      write(...hostedLogValues(message, values));
  };
  log.setLevel(log.getLevel());
};
